    /**
     * Bounced emails are delivery failures just like STATUS_FAILED ones.
     * A window with enough bounced-only emails above the threshold must
     * produce a failed result — the check must not ignore them.
     */
    public function test_mail_check_fails_when_bounced_emails_exceed_threshold(): void
    {
        // 4 bounced + 2 sent = 6 total (above min_samples of 5).
        // Bounce rate = 4/6 ≈ 67%, well above the 25% threshold.
        for ($i = 0; $i < 4; $i++) {
            $this->emailWith(AuditEmailLog::STATUS_BOUNCED);
        }
        for ($i = 0; $i < 2; $i++) {
            $this->emailWith(AuditEmailLog::STATUS_SENT);
        }

        $result = (new MailFailureRateCheck)->run();

        $this->assertSame('failed', $result->status->value, 'Bounced emails must count as failures');
        $this->assertSame(6, $result->meta['total']);
        $this->assertSame(4, $result->meta['failed']);
        $this->assertSame(67, $result->meta['percent']);
    }
}

